/**
 * The interface language toggle: the shell, the stepper and the step text switch to Hindi (hi.json, generated by
 * scripts/translate_ui_hi.py), the choice survives a reload, the page language is set, and English comes back.
 */
import { expect, test } from "@playwright/test";
import { MockBackend } from "./mockBackend";
import { TID } from "./testids";
import hi from "../lib/i18n/hi.json";

const HI = hi as Record<string, string>;

test.beforeEach(async ({ page }) => {
  await MockBackend.install(page, { caseId: "case-0007", gate1Approved: true, draft: "done" });
  await page.goto("/case/case-0007");
  await expect(page.getByTestId(TID.stageRail)).toBeVisible();
});

test("the toggle switches the interface to Hindi and back", async ({ page }) => {
  const toggle = page.getByTestId("lang-toggle");
  await expect(toggle).toHaveText("हिन्दी");
  await expect(page.getByTestId(TID.stage("II"))).toContainText("Review facts");

  await toggle.click();
  await expect(page.locator("html")).toHaveAttribute("lang", "hi");
  await expect(page.getByTestId(TID.stage("II"))).toContainText(HI["Review facts"]);
  await expect(page.getByTestId("new-case-button")).toContainText(HI["New case"]);
  await expect(toggle).toHaveText("English");

  await page.getByTestId(TID.stage("II")).click();
  await expect(page.locator("#step-title")).toHaveText(HI["Review facts"]);

  await toggle.click();
  await expect(page.locator("html")).toHaveAttribute("lang", "en");
  await expect(page.getByTestId(TID.stage("II"))).toContainText("Review facts");
});

test("the choice survives a reload", async ({ page }) => {
  await page.getByTestId("lang-toggle").click();
  await page.reload();
  await expect(page.getByTestId(TID.stageRail)).toBeVisible();
  await expect(page.locator("html")).toHaveAttribute("lang", "hi");
  await expect(page.getByTestId(TID.stage("II"))).toContainText(HI["Review facts"]);
});
